  const SEEN21 = 'Harvard CS50 AI Quiz 5; MIT 6.034 Quiz 3 (2009); Berkeley CS188 finals';
  Q[21] = [
    { lvl: 1, type: 'num', q: 'What is the derivative of the sigmoid g(z) = 1/(1 + e<sup>−z</sup>) at z = 0?', a: 0.25, tol: 0.001, explain: 'g′(z) = g(z)(1 − g(z)) = 0.5 × 0.5 = 0.25, its maximum. Products of many such factors shrink: the vanishing gradient.' },
    { lvl: 2, type: 'num', q: 'A 3×3 convolution with 16 input channels and 32 output channels, each output channel with its own bias, has how many parameters?', a: 4640, tol: 0.5, explain: '3 × 3 × 16 weights per output channel × 32 = 4,608, plus 32 biases = 4,640.' },
    { lvl: 1, type: 'num', q: 'A 9×9 image is convolved with a 3×3 kernel, with zero padding of 1 and stride 2. How many rows does the output have?', a: 5, tol: 0.01, explain: '⌊(9 + 2 − 3)/2⌋ + 1 = 5.', seen: SEEN21 },
    { lvl: 2, type: 'num', q: 'A single sigmoid unit computes ŷ = g(wx + b) with w = 0.5, x = 2, b = −1. The target is y = 1 and the loss is (y − ŷ)². What is ∂Loss/∂w?', a: -0.5, tol: 0.001, explain: 'z = 0, so ŷ = 0.5. ∂Loss/∂ŷ = −2(1 − 0.5) = −1, g′ = 0.25, so ∂Loss/∂z = −0.25 and ∂Loss/∂w = −0.25 × x = −0.5.' },
    { lvl: 1, type: 'mcq', q: 'A network built only from linear units, however many layers deep, computes:', opts: ['Any continuous function', 'A linear function of its input', 'A step function', 'A polynomial of degree equal to the number of layers'], a: 1, explain: 'A composition of linear maps is linear; non-linear activations are what give depth its power.', seen: SEEN21 },
    { lvl: 1, type: 'mcq', q: 'For multi-class classification, the usual output layer and loss are:', opts: ['Linear output and squared error', 'Softmax output and cross-entropy loss', 'Sigmoid output and hinge loss', 'ReLU output and absolute error'], a: 1, explain: 'Softmax gives a distribution over classes; cross-entropy is minus the log probability of the correct class.' },
    { lvl: 1, type: 'mcq', q: 'What does dropout do during training?', opts: ['Removes training examples', 'Randomly deactivates units during training to reduce overfitting', 'Lowers the learning rate', 'Deletes layers that do not help'], a: 1, explain: 'It discourages co-adaptation of units and acts like training an ensemble of thinned networks.' },
    { lvl: 2, type: 'mcq', q: '2×2 max-pooling with stride 2 is applied to the 4×4 map [[1, 3, 2, 0], [4, 2, 1, 5], [0, 1, 3, 2], [2, 6, 1, 0]]. The result is:', opts: ['[[4, 5], [6, 3]]', '[[3, 5], [6, 3]]', '[[4, 2], [6, 2]]', '[[2.5, 2], [2.25, 1.5]]'], a: 0, explain: 'The maximum of each 2×2 block: {1,3,4,2} → 4, {2,0,1,5} → 5, {0,1,2,6} → 6, {3,2,1,0} → 3. The last option is average pooling.', seen: 'Harvard CS50 AI Quiz 5' },
    { lvl: 1, type: 'tf', q: 'A network with a single, large enough hidden layer can approximate any continuous function on a bounded region to any desired accuracy.', a: true, explain: 'This is the universal approximation result; it says nothing about how many units are needed or whether training will find the weights.' }
  ];

